// SUITE_NAME.ini: [module] or [module.subsection] headers, key=value, # comments. The names in the ini are the public ones
// (tools/ini_names.tsv, core/inimap.h); the param tables below keep their internal keys, and a legacy ini ([cruise] acc_short_s)
// still loads: an internal key under its plain module header is found too.
// The compiled defaults are the developer's; a player who has no ini (or an old one without a new key) gets the
// standard preset instead (preset_standard.inc, generated by tools/gen_ini.py inc; else a deleted ini would mean the
// developer's wheel buttons, experimental lane steering and big csv traces). A missing file is written with those values
// and the help lines. Values are checked for sanity (finite, within bounds) and the effective values go into the log.
#include "suite.h"
#include "vehicle.h"
#include "inifile.h"
#include "inimap.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>

// [core]: settings of the suite itself; its hooks are the actuator's (core/actuate.cpp), which start before the modules.
static float p_log_level, p_log_max_mb, p_csv_max_mb, p_incident_mb;
static float p_brake_pedal_hook, p_brake_light_hook, p_retarder_feed_hook;
static param g_params[] = {
    { "incident_mb", &p_incident_mb, 40, "incidents folder: something went wrong (hunting gearbox, a shift you fought, rpm limiter, stuck in neutral, AEB, ...) = one file with the 20 s before and 15 s after, with the log lines of that time. The folder is kept under this size (MB), oldest first; 0 = no incident files" },
    { "log_level", &p_log_level, 2, "dazdrive.log: 0 = start-up, errors, mode changes and one line per incident, 1 = + every shift and the modules' detail lines, 2 = + periodic traces and the csv trace files. The detail lines of level 1 are in every incident file anyway" },
    { "csv_max_mb", &p_csv_max_mb, 5, "a csv trace (log_level 2 only) moves to <name>.1 and starts again beyond this size (MB, 0.5-200): ~2.5 hours of driving per file" },
    { "log_max_mb", &p_log_max_mb, 5, "dazdrive.log moves to dazdrive.log.1 and starts again beyond this size (MB, 0.2-100). The log of the previous session stays as dazdrive.prev.log" },
    { "retarder_hook", &g_retarder_hook, 1, "1 = install a hook on the retarder torque of the game's drivetrain, so that the suite can scale the retarder for the player's truck. The deceleration assist uses it for its soften, ramp_s and pre_blend; nothing else scales the retarder, so otherwise the torque stays exactly as the game sets it. The dashboard, the animation and the lever keep showing the game's own retarder step. 0 = the game's retarder is left alone" },
    { "brake_learn", &g_brake_learn, 1, "1 = the suite learns how the truck brakes and keeps it per truck (brake_gain.txt, brake_model.txt): the service brake's gain from steady braking, by you or by it (the force per request, so a load change keeps it valid), the retarder's force per stage, the engine brake's per stage. Every module that sizes a brake request or counts on the retarder or the engine brake (the emergency braking, the ACC, the deceleration assist, the planner, the brake channel, the holds) asks this one model; it starts from values derived from the truck's mass and engine and moves to what was measured, a figure far above the start value only as far as the events behind it carry it. 0 = nothing is measured or stored; the start values still answer" },
    { "dash_messages", &g_dash_messages, 0, "1 = the short dashboard letters of the other modules (ACC distance, ISA, lane keeping, crawl mode, hill start and Auto Hold) are also shown while TrueShift does not show its mode letter (TrueShift off, its dash_letter 0, or a truck it leaves to the game); when they are over, the letter the game had comes back. 0 = they are only shown over TrueShift's mode letter" },
    { "input_device", &g_input_device, 1, "1 = register the plugin's own input device with the game (SDK input, no binding needed): the plugin can then press a few game controls itself (the lift axle, the high beam) when a feature of it is set to act. Nothing is pressed unless such a feature is on. 0 = no device" },
    { "brake_pedal_hook", &p_brake_pedal_hook, 0, "1 = install a hook on the brake pedal inside the game's pedal code, so that a feature of the suite can shape how hard the pedal brakes. Until one does, the truck brakes exactly as without the hook; a full press always brakes in full. 0 = the game's pedal code is left alone" },
    { "brake_light_hook", &p_brake_light_hook, 0, "1 = install a hook on the game's brake light decision, so that a feature of the suite can switch the brake lights on while it brakes. It only ever adds: a light the game switches on stays on. Until a feature uses it, the lights are as without the hook. 0 = the game decides the brake lights alone" },
    { "retarder_feed_hook", &p_retarder_feed_hook, 1, "1 = install a hook where the game sets the retarder demand, so that a feature of the suite can add retarder braking on top of the game's. The brake channel uses it to carry braking with the retarder (the brake pedal's blend can too). The game's own demand (the lever, the cruise, the automatic retarder) is kept whenever it is higher. 0 = the game's retarder demand is left alone" },
    { "air_from_truck", &g_air_from_truck, 0, "1 = the brake air edges follow the truck's own warning pressure (reported by the game per truck): the suite's brake requests pause 10 psi over it (instead of [cruise] air_min_psi), the emergency braking saves air below 25 psi over it (instead of 90), the gearbox keeps the rpm up to charge the air below 35 psi over it (instead of [trueshift] air_charge_psi). A truck with a 65 psi warning gets the fixed values; a truck that does not report it keeps them too, and a rule set to 0 stays off. 0 = the fixed values" },
    { "vehicle_class", &g_vehicle_class, 0, "which vehicle the suite is driving: 0 = auto (a vehicle whose own mass, without a trailer, is at most 3.5 t, or any car, is a light vehicle: no truck speed limiter, the rollover guard off, car emergency-hazard, ACC and AEB thresholds, hydraulic brakes, car-tuned lane assist; with a trailer it keeps a lower cap instead of the truck limiter), 1 = always a truck, 2 = always a light vehicle. The words auto / truck / light are accepted in the ini too" },
};
// The actuator's hooks, then the brake hooks [core] asks for (all three off by default: nothing uses them yet).
static void core_start()
{
    act_start();
    game_brake_hooks_start(p_brake_pedal_hook >= 0.5f, p_brake_light_hook >= 0.5f, p_retarder_feed_hook >= 0.5f);
}
module m_core = { "core", "Core", g_params, sizeof g_params / sizeof g_params[0], core_start, disp_frame, NULL, act_stop, act_reset, act_status, NULL, VCM_BOTH };

